          nullif(trim(ag.city), ''),
          nullif(trim(ag.area), ''),
          nullif(trim(s.destination_city), ''),
          nullif(trim(dlr.destination), ''),
          '\u063A\u064A\u0631 \u0645\u062D\u062F\u062F'
