// server/src/routes/branchRoutes.ts
var import_express8 = __toESM(require_express2(), 1);
init_zod();
var createSchema = external_exports.object({
  code: external_exports.string().min(1),
  name: external_exports.string().min(1),
  city: external_exports.string().optional(),
  address: external_exports.string().optional(),
  phone: external_exports.string().optional(),
  is_active: external_exports.boolean().optional()
});
var updateSchema = createSchema.partial();
function requireCompanyId(req) {
  const companyId = req.requestUserContext?.companyId;
  if (!companyId) {
    throw new HttpError(403, "Company scope is required.");
  }
  return companyId;
}
function parseBoolFlag(value) {
  if (typeof value !== "string") return false;
  return value === "1" || value.toLowerCase() === "true";
}
function createBranchRouter(repository) {
  const router3 = (0, import_express8.Router)();
  const auditService3 = new AuditService();
  router3.get(
    "/",
    requirePermissions(["settings.branches.read"]),
    asyncHandler(async (req, res) => {
      const companyId = requireCompanyId(req);
      const includeInactive = parseBoolFlag(req.query.includeInactive);
      const data = await repository.listBranches(companyId, includeInactive);
      res.json({ success: true, data });
    })
  );
  router3.post(
    "/",
    requirePermissions(["settings.branches.write"]),
    asyncHandler(async (req, res) => {
      const companyId = requireCompanyId(req);
      const payload = createSchema.parse(req.body);
      const data = await repository.createBranch(companyId, payload);
      auditService3.logAsync({
        req,
        action: "BRANCH_CREATED",
        entityType: "branch",
        entityId: data.id,
        metadata: {
          code: data.code,
          name: data.name
        }
      });
      res.status(201).json({ success: true, data });
    })
  );
  router3.put(
    "/:id",
    requirePermissions(["settings.branches.write"]),
    asyncHandler(async (req, res) => {
      const companyId = requireCompanyId(req);
      const payload = updateSchema.parse(req.body);
      const data = await repository.updateBranch(String(req.params.id), companyId, payload);
      if (!data) {
        res.status(404).json({ success: false, error: "Branch not found." });
        return;
      }
      auditService3.logAsync({
        req,
        action: "BRANCH_UPDATED",
        entityType: "branch",
        entityId: String(req.params.id),
        metadata: {
          changedFields: Object.keys(payload)
        }
      });
      res.json({ success: true, data });
    })
  );
  router3.delete(
    "/:id",
    requirePermissions(["settings.branches.write"]),
    asyncHandler(async (req, res) => {
      const companyId = requireCompanyId(req);
      const removed = await repository.deactivateBranch(String(req.params.id), companyId);
      if (!removed) {
        res.status(404).json({ success: false, error: "Branch not found." });
        return;
      }
      auditService3.logAsync({
        req,
        action: "BRANCH_DEACTIVATED",
        entityType: "branch",
        entityId: String(req.params.id)
      });
      res.json({ success: true });
    })
  );
  return router3;
}

